DB_PATH = os.environ.get("UNG_PRESIDENT_DB_PATH", os.path.join(os.path.dirname(os.path.abspath(__file__)), "ung_president.db"))
DATABASE_URL = os.environ.get("DATABASE_URL", "")
SECRET_KEY = os.environ.get("UNG_PRESIDENT_SECRET")
if not SECRET_KEY:
    if os.environ.get("RAILWAY_ENVIRONMENT_ID"):
        raise RuntimeError("Set UNG_PRESIDENT_SECRET to a persistent random secret before deployment.")
    secret_path = DB_PATH + ".secret"
    os.makedirs(os.path.dirname(os.path.abspath(secret_path)), exist_ok=True)
    try:
        fd = os.open(secret_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError:
        with open(secret_path) as source:
            SECRET_KEY = source.read().strip()
    else:
        SECRET_KEY = secrets.token_hex(32)
        with os.fdopen(fd, "w") as target:
            target.write(SECRET_KEY)
PBKDF2_ITERATIONS = 260_000
LOCKOUT_THRESHOLD = 5
LOCKOUT_MINUTES = 15
SESSION_MAX_AGE_SECONDS = 60 * 60 * 8
REG_TOKEN_MAX_AGE_SECONDS = 60 * 20  # 20 minutes to complete the details form after code verification
