def render(name, **ctx):
    ctx.setdefault("css", CSS)
    ctx.setdefault("nat_flag_b64", NAT_FLAG_B64)
    ctx.setdefault("pres_seal_b64", PRES_SEAL_B64)
    ctx.setdefault("vp_seal_b64", VP_SEAL_B64)
    return env.get_template(name).render(**ctx)
def render_admin(page_title, inner_template, **ctx):
    ctx.setdefault("pres_seal_b64", PRES_SEAL_B64)
    inner_html = env.from_string(inner_template).render(**ctx)
    ctx["css"] = CSS
    ctx["page_title"] = page_title
    ctx["inner"] = Markup(inner_html)
    return env.get_template("admin_shell").render(**ctx)
