@app.post("/admin/login")
def login(request: Request, username: str = Form(...), password: str = Form(...)):
    ip = client_ip(request)
    if is_rate_limited(f"login:{ip}", 10, 300):
        return RedirectResponse("/admin/login?error=Too+many+attempts.+Try+later.", status_code=303)
    with db_cursor() as cur:
        cur.execute("SELECT * FROM users WHERE username=?", (username,))
        user = cur.fetchone()
    if not user:
        log_action(None, username, "login_failed_unknown_user", ip_address=ip)
        return RedirectResponse("/admin/login?error=Invalid+credentials", status_code=303)
    if is_locked(user["locked_until"]):
        log_action(user["id"], username, "login_blocked_locked", ip_address=ip)
        return RedirectResponse("/admin/login?error=Account+locked.+Try+again+later.", status_code=303)
    if not verify_password(password, user["password_hash"], user["salt"]):
        attempts = user["failed_attempts"] + 1
        locked_until = None
        if attempts >= LOCKOUT_THRESHOLD:
            locked_until = compute_lockout_expiry()
            attempts = 0
        with db_cursor(commit=True) as cur:
            cur.execute("UPDATE users SET failed_attempts=?, locked_until=? WHERE id=?", (attempts, locked_until, user["id"]))
        log_action(user["id"], username, "login_failed_bad_password", ip_address=ip)
        return RedirectResponse("/admin/login?error=Invalid+credentials", status_code=303)
    with db_cursor(commit=True) as cur:
        cur.execute("UPDATE users SET failed_attempts=0, locked_until=NULL, last_login=? WHERE id=?", (datetime.utcnow().isoformat(), user["id"]))
    log_action(user["id"], username, "login_success", ip_address=ip)
    token = create_session_token(user["id"], user["username"], user["role"])
    response = RedirectResponse("/admin", status_code=303)
    response.set_cookie("session", token, httponly=True, samesite="strict", max_age=SESSION_MAX_AGE_SECONDS, secure=bool(os.environ.get("RAILWAY_ENVIRONMENT_ID")) or os.environ.get("UNG_PRESIDENT_COOKIE_SECURE") == "1")
    return response
