@app.post("/admin/register")
def register_code_submit(request: Request, code: str = Form(...)):
    ip = client_ip(request)
    if is_rate_limited(f"register:{ip}", 8, 900):
        return RedirectResponse("/admin/register?error=Too+many+attempts.+Try+later.", status_code=303)
    code_hash = hash_hr_code(code)
    with db_cursor() as cur:
        cur.execute("SELECT * FROM hr_codes WHERE code_hash=?", (code_hash,))
        row = cur.fetchone()
    if not row or row["is_used"]:
        log_action(None, None, "hr_code_invalid_attempt", ip_address=ip)
        return RedirectResponse("/admin/register?error=Invalid+or+already-used+code.", status_code=303)
    token = create_reg_token(row["id"], row["role"])
    log_action(None, None, "hr_code_verified", "hr_codes", row["id"], ip_address=ip)
    return RedirectResponse(f"/admin/register/details?token={token}", status_code=303)
